    condition {{
      test = "StringEquals"
      variable = "{sub}"
      values = ["{subject}"]
    }}
  }}
}}
''')
    return d
cases = [
  ("literal",        "token.actions.githubusercontent.com:aud", "token.actions.githubusercontent.com:sub", "repo:${local.r}:ref:refs/heads/main", True, True),
